using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using System.Windows.Forms;
namespace ScoreModern {
 public sealed partial class Editor {
  internal void CheckInterfaceFonts(string output){Directory.CreateDirectory(output);string previous=NativeUiFont.Family;var original=score.Encode();int fonts=0,fields=0,rasters=0;try{NativeInterfaceText.SetConsolas(false);
   foreach(string family in new[]{"Consolas","Ebrima","Segoe UI","Arial","Times New Roman"}){if(!FontFamily.Families.Any(f=>f.Name==family))continue;NativeUiFont.Set(family,false);
    foreach(float size in new[]{12f,21f,24f})using(var actual=new Bitmap(1400,100))using(var expected=new Bitmap(1400,100))using(var a=Graphics.FromImage(actual))using(var e=Graphics.FromImage(expected))using(var font=new Font(family,size,FontStyle.Regular,GraphicsUnit.Pixel))using(var format=(StringFormat)StringFormat.GenericTypographic.Clone()){
     format.FormatFlags|=StringFormatFlags.NoWrap|StringFormatFlags.MeasureTrailingSpaces;string line="Staff = 1   iii WWW 012345.67 / Spacing = R   Résumé fi";a.Clear(Color.White);e.Clear(Color.White);NativeInterfaceText.Draw(a,line,font,Brushes.Black,new RectangleF(0,0,1400,100));e.DrawString(line,font,Brushes.Black,new RectangleF(0,0,1400,100),format);for(int y=0;y<100;y++)for(int x=0;x<1400;x++)if(actual.GetPixel(x,y)!=expected.GetPixel(x,y))throw new Exception("Windows font spacing differs: "+family+" "+size);if(family!="Consolas"&&NativeInterfaceText.TextWidth(a,"iiii",font)>=NativeInterfaceText.TextWidth(a,"WWWW",font))throw new Exception("Proportional widths were flattened: "+family);actual.Save(Path.Combine(output,family.Replace(' ','-')+"-"+size+".png"));rasters++;
    }
    Function(2);UpdateMusicInput();LayoutClassic();foreach(var row in new[]{(NativeTextLabel)inputStaffLine,(NativeTextLabel)contextLine}){var spans=setupSpans[row];int first=row==inputStaffLine?1:6;for(int n=0;n<spans.Length;n++){var box=InputFieldBounds(row,spans[n]);ClickInputField(row,first,new MouseEventArgs(MouseButtons.Left,1,(int)((box.Left+box.Right)/2),Math.Max(1,row.Height/2),0));if(setupEditField!=first+n||!setupValueBox.Visible||setupValueBox.Font.FontFamily.Name!=family)throw new Exception("F2 proportional-font click/edit differs: "+family+" field "+(first+n));var value=InputFieldBounds(row,setupSpans[row][n],true);if(Math.Abs(setupValueBox.Left-Math.Floor(value.Left))>1)throw new Exception("F2 editor is displaced from its text.");CloseInputFieldEditor();fields++;}}LeaveMusicInput();
    StartOriginalTextSetup();for(int n=0;n<originalTextSetupSpans.Length;n++){var row=(NativeTextLabel)contextLine;var box=InputFieldBounds(row,originalTextSetupSpans[n]);typeof(Control).GetMethod("OnMouseClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(row,new object[]{new MouseEventArgs(MouseButtons.Left,1,(int)((box.Left+box.Right)/2),Math.Max(1,row.Height/2),0)});if(originalTextSetupField!=n||!originalTextValueBox.Visible||originalTextValueBox.Font.FontFamily.Name!=family)throw new Exception("F4 proportional-font click/edit differs: "+family+" field "+n);CloseOriginalTextValue();fields++;}OriginalTextSetupKey(new KeyEventArgs(Keys.Escape));if(!original.SequenceEqual(score.Encode()))throw new Exception("UI font test changed MUS data.");fonts++;
   }Console.WriteLine("PASS "+fonts+" UI fonts / "+rasters+" natural-spacing rasters / "+fields+" F2/F4 click/editor positions; MUS unchanged.");
  }finally{NativeUiFont.Set(previous,false);}}
 }
 public static class NativeInterfaceFontChecks {public static int Run(string[] args){try{using(var editor=new Editor(args[1],args[2])){editor.Show();Application.DoEvents();editor.CheckInterfaceFonts(args[3]);editor.Close();}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}}
}
